const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Keep the lease for the full frontend/sidecar lifetime, including synchronous
// TUI dispatch. Maintenance recovery acquires its own exclusive lease instead.
const startupArgs = process.argv.slice(2);
const { acquireClientLease, releaseClientLease, clientInvocationKind } = await import("./core/client_lease.js");
const invocationKind = clientInvocationKind(startupArgs);
const startupReadOnly = invocationKind === "metadata" || (startupArgs[0] === "upgrade" && startupArgs.includes("--check"));
let operatorConfigStartupError: Error | undefined;
// `upgrade --check` is read-only, so it must not replay a transaction. It also
// must not load configuration while a restore journal says that config may be
// only partially applied. Refuse before loadEnvironment() and let a normal
// managed launch perform recovery.
if (startupArgs[0] === "upgrade" && startupArgs.includes("--check")) {
  try {
    const { hasPendingStateRestore } = await import("./core/state_restore.js");
    if (hasPendingStateRestore(process.env.HOME || os.homedir())) {
      throw new Error("Pending state restore must be recovered before running upgrade --check");
    }
  } catch (error: any) {
    console.error(`[maintenance] ${error?.message ?? "Nexus restore state could not be verified"}`);
    process.exit(2);
  }
}
// A durable state-restore intent must be replayed before environment/config
// loading or any normal client is admitted. The recovery command takes the
// exclusive lifetime lease; ordinary clients take their shared lease below.
if (invocationKind === "restore" || (invocationKind === "client" && !startupReadOnly)) {
  try {
    const { hasPendingStateRestore, recoverPendingStateRestore } = await import("./core/state_restore.js");
    const home = process.env.HOME || os.homedir();
    if (hasPendingStateRestore(home) && !recoverPendingStateRestore(home)) {
      throw new Error("Pending state restore could not be recovered; no state was admitted");
    }
  } catch (error: any) {
    console.error(`[maintenance] ${error?.message ?? "Nexus restore recovery failed closed"}`);
    process.exit(2);
  }
}
if (invocationKind === "client") {
  try {
    const lease = acquireClientLease(process.env.HOME || os.homedir());
    process.once("exit", () => releaseClientLease(lease));
  } catch (error: any) {
    console.error(`[maintenance] ${error.message}`);
    process.exit(2);
  }
  loadEnvironment();
  operatorConfigStartupError = operatorConfigLoadError();
}

async function recoverInterruptedUpgrade(topLevelCommand: string): Promise<void> {
  // Diagnose interrupted upgrades before launching a new CLI/TUI session.
  // Read-only version/help/check commands never recover or write state.
  if (startupReadOnly || topLevelCommand === "upgrade" || process.env.NEXUS_UPGRADE_HEALTH_CHECK === "1" || !process.env.NEXUS_HOME) return;

  const { getJournalPath, readJournal, recoverUpgrade } = await import("./upgrade_journal.js");
  const packagedPrefix = path.resolve(process.env.NEXUS_HOME, "../../..");
  const journal = readJournal(packagedPrefix);
  if ((journal && !["idle", "complete", "rolled_back"].includes(journal.state)) || (!journal && fs.existsSync(getJournalPath(packagedPrefix)))) {
    const outcome = recoverUpgrade(packagedPrefix);
    if (outcome.action === "upgrade_in_progress") console.error(`[upgrade] ${outcome.details}`);
    if (outcome.action === "manual_intervention") {
      console.error(`[upgrade] ${outcome.details}. Run nexus upgrade --recover after resolving the recorded failure.`);
      process.exit(2);
    }
    if (outcome.recovered) console.warn(`[upgrade] ${outcome.details}`);
  }
}

/**
 * Exits once stdout and stderr have accepted everything written so far. A write to a pipe is asynchronous, so an immediate
 * `process.exit()` drops whatever the pipe has not yet taken (65,536 bytes on Linux) while still exiting with the intended code.
 */
function exitAfterFlush(code: number): void {
  let pending = 2;
  const done = () => { if (--pending === 0) process.exit(code); };
  process.stdout.write("", done);
  process.stderr.write("", done);
}

import { getBuildIdentity } from "./build_identity.js";

function isExecutable(filePath: string): boolean {
  try {
    fs.accessSync(filePath, fs.constants.X_OK);
    return fs.statSync(filePath).isFile();
  } catch {
    return false;
  }
}

function resolveTuiBinary(): string | undefined {
  if (process.env.NEXUS_TUI_BIN && isExecutable(process.env.NEXUS_TUI_BIN)) {
    return process.env.NEXUS_TUI_BIN;
  }
  if (process.env.NEXUS_HOME) {
    const packaged = path.join(process.env.NEXUS_HOME, "lib", "core", "nexus-tui");
    if (isExecutable(packaged)) return packaged;
  }
  const root = process.env.NEXUS_ROOT || path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
  const releaseTui = path.join(root, "core", "target", "release", "nexus-tui");
  if (isExecutable(releaseTui)) return releaseTui;
  const debugTui = path.join(root, "core", "target", "debug", "nexus-tui");
  if (isExecutable(debugTui)) return debugTui;
  return undefined;
}

function resolveSidecarScript(): string | undefined {
  if (process.env.NEXUS_SIDECAR && fs.existsSync(process.env.NEXUS_SIDECAR)) {
    return process.env.NEXUS_SIDECAR;
  }
  if (process.env.NEXUS_HOME) {
    const packaged = path.join(process.env.NEXUS_HOME, "lib", "cli", "dist", "sidecar.js");
    if (fs.existsSync(packaged)) return packaged;
  }
  const root = process.env.NEXUS_ROOT;
  if (root) {
    const rootSidecar = path.join(root, "cli", "dist", "sidecar.js");
    if (fs.existsSync(rootSidecar)) return rootSidecar;
  }
  const currentDir = path.dirname(fileURLToPath(import.meta.url));
  const direct = path.join(currentDir, "sidecar.js");
  if (fs.existsSync(direct)) return direct;
  const repoRoot = path.resolve(currentDir, "..", "..");
  const checkout = path.join(repoRoot, "cli", "dist", "sidecar.js");
  if (fs.existsSync(checkout)) return checkout;
  return undefined;
}

function spawnTui(tuiBin: string, sidecarScript: string): void {
  const passthrough = process.argv.slice(2).filter((arg) => arg !== "--live" && arg !== "--repl");
  const result = spawnSync(
    tuiBin,
    ["--live", "--sidecar", sidecarScript, "--node", process.execPath, "--", ...passthrough],
    { stdio: "inherit" }
  );
  if (result.error) {
    console.error(`Failed to launch nexus-tui: ${result.error.message}`);
    process.exit(1);
  }
  process.exit(result.status ?? (result.signal ? 1 : 0));
}

function triggerBackgroundGc(): void {
  void import("./core/retention.js").then(({ maybeRunDailyGc }) => {
    maybeRunDailyGc().then((res) => {
      if (res.status === "needs_acknowledgement" && res.notice) {
        console.error(pc.yellow(`\n[Notice] ${res.notice}\n`));
      }
    }).catch(() => {});
  }).catch(() => {});
}

async function startRepl(options: any): Promise<void> {
  if (process.env.NEXUS_TEST_RECORD_REPL) {
    const log = process.env.NEXUS_TEST_RECORD_REPL;
    const parts = ["repl"];
    if (options.model) parts.push("-m", options.model);
    if (options.resume) parts.push("-r", typeof options.resume === "string" ? options.resume : "");
    fs.appendFileSync(log, parts.join(" ").trim() + "\n");
    return;
  }
  const trustDecision = await promptWorkspaceTrust(options.workspace ? path.resolve(options.workspace) : process.cwd());
  if (trustDecision === "exit") return;
  triggerBackgroundGc();
  const config = buildConfig(options);
  if (config.model === "local-model") {
    try {
      const client = new LocalLlmClient(config);
      const models = await client.listModels();
      if (models.length > 0) {
        config.model = models[0];
      }
    } catch {
      // Fallback
    }
  }
  const resumeId = typeof options.resume === "string" ? options.resume : options.resume ? "latest" : undefined;
  if (config.provider || config.plannerProvider || config.coderProvider) console.error(pc.dim(describeTarget(config)));
  config.surface = "repl";
  const app = new ApplicationCore(config);
  const repl = new InteractiveRepl(app, config.approvalMode, resumeId);
  await repl.start();
}

async function runDefault(options: any): Promise<void> {
  if (options.repl) {
    await startRepl(options);
    return;
  }

  const tuiBin = resolveTuiBinary();
  const sidecarScript = resolveSidecarScript();

  if (options.live) {
    if (!tuiBin) {
      console.error("nexus-tui is not built. Run 'make build' first.");
      process.exit(1);
    }
    if (!sidecarScript) {
      console.error("nexus sidecar is not built. Run 'npm run build' in cli first.");
      process.exit(1);
    }
    const trustDecision = await promptWorkspaceTrust(options.workspace ? path.resolve(options.workspace) : process.cwd());
    if (trustDecision === "exit") return;
    triggerBackgroundGc();
    spawnTui(tuiBin, sidecarScript);
    return;
  }

