    return {
      benchmarkName,
      timestamp: new Date().toISOString(),
      totalInstances: instances.length,
      resolvedCount,
      unresolvedCount,
      errorCount,
      passRatePercentage,
      totalTokensConsumed,
      avgDurationSeconds,
      results,
