  results: [{
    instanceId: "task-1",
    repo: "example/repo",
    resolved: true,
    status: "RESOLVED",
    durationMs: 500,
    tokensConsumed: { prompt: 8, completion: 4, total: 12 },
    stepsTaken: 2,
    patchDiff: "private patch text",
    testOutput: "private test output",
  }],
};

function runner(onRun: () => void): EvalRunner {
  return {
    loadDataset: () => [{ instance_id: "task-1", repo: "example/repo", problem_statement: "task" }],
    createEvaluator: () => ({
      runBenchmark: async (_instances: SweBenchInstance[], _config: HarnessConfig) => {
        onRun();
        return summary;
      },
    }),
  };
}

test("parseEvalRuns accepts only positive safe whole numbers", () => {
  assert.equal(parseEvalRuns(undefined), 1);
  assert.equal(parseEvalRuns("3"), 3);
  for (const value of ["0", "-1", "1.5", " 2", "2x", "9007199254740992"]) {
    assert.throws(() => parseEvalRuns(value), /positive whole number|integer range/);
  }
});

test("startup HOME isolation is limited to eval --isolated-home and restores the caller environment", () => {
  const originalHome = process.env.HOME;
  assert.equal(isolateEvalCommandHome(["run", "--isolated-home"]), undefined);
  const restore = isolateEvalCommandHome(["eval", "--isolated-home"]);
  assert.equal(typeof restore, "function");
  const isolatedHome = process.env.HOME;
  try {
    assert.ok(isolatedHome && isolatedHome !== originalHome);
    assert.equal(process.env.XDG_CONFIG_HOME, path.join(isolatedHome ?? "", ".config"));
  } finally {
    restore?.();
  }
  assert.equal(process.env.HOME, originalHome);
  assert.ok(isolatedHome && !fs.existsSync(isolatedHome));
});

test("runEvalCommand repeats evaluation and writes a structured score without free-form output", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-cli-test-"));
  const output = path.join(root, "scores", "score.json");
  let runCount = 0;
  try {
    const result = await runEvalCommand(
      { dataset: "dataset.jsonl", runs: "2", output },
      () => ({ workspace: root } as HarnessConfig),
      runner(() => { runCount++; }),
    );

    assert.equal(runCount, 2);
    assert.equal(result.schemaVersion, 1);
    assert.equal(result.runs, 2);
    assert.deepEqual(result.scores.map((score) => score.run), [1, 2]);
    assert.equal(result.scores[0].results[0].tokensConsumed, 12);
    const written = fs.readFileSync(output, "utf8");
    assert.deepEqual(JSON.parse(written), result);
    assert.equal(written.includes("private patch text"), false);
    assert.equal(written.includes("private test output"), false);
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("isolated-home gives every run a separate private home and restores the caller environment", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-home-test-"));
  const originalHome = process.env.HOME;
  const observedHomes: string[] = [];
  try {
    const result = await runEvalCommand(
      { dataset: "dataset.jsonl", runs: 2, isolatedHome: true },
      () => {
        observedHomes.push(process.env.HOME ?? "");
        assert.equal(process.env.XDG_CONFIG_HOME, path.join(process.env.HOME ?? "", ".config"));
        return { workspace: root } as HarnessConfig;
      },
      runner(() => { observedHomes.push(process.env.HOME ?? ""); }),
    );

    assert.equal(result.isolatedHome, true);
    assert.equal(new Set(observedHomes).size, 2);
    assert.ok(observedHomes.every((home) => home !== originalHome));
    assert.equal(process.env.HOME, originalHome);
    assert.ok(observedHomes.every((home) => !fs.existsSync(home)));
  } finally {
    if (originalHome === undefined) delete process.env.HOME;
    else process.env.HOME = originalHome;
    fs.rmSync(root, { recursive: true, force: true });
  }
