}

function withRunHome<T>(isolatedHome: boolean, run: () => Promise<T>): Promise<T> {
  if (!isolatedHome) return run();

  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-home-"));
  fs.chmodSync(home, 0o700);
  const isolatedEnvironment: Record<string, string> = {
    HOME: home,
    XDG_CONFIG_HOME: path.join(home, ".config"),
    XDG_DATA_HOME: path.join(home, ".local", "share"),
    XDG_STATE_HOME: path.join(home, ".local", "state"),
    XDG_CACHE_HOME: path.join(home, ".cache"),
  };
  const previousEnvironment = new Map(Object.keys(isolatedEnvironment).map((key) => [key, process.env[key]]));
  Object.assign(process.env, isolatedEnvironment);
  const restoreEnvironment = () => {
    for (const [key, value] of previousEnvironment) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  };
  try {
    return run().finally(() => {
      restoreEnvironment();
      fs.rmSync(home, { recursive: true, force: true });
    });
  } catch (error) {
    restoreEnvironment();
    fs.rmSync(home, { recursive: true, force: true });
    throw error;
  }
}

/** Isolate launcher startup state before the client lease and environment loader run. */
export function isolateEvalCommandHome(args: readonly string[]): (() => void) | undefined {
  if (args[0] !== "eval" || !args.includes("--isolated-home")) return undefined;

  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-cli-home-"));
  fs.chmodSync(home, 0o700);
  const isolatedEnvironment: Record<string, string> = {
    HOME: home,
    XDG_CONFIG_HOME: path.join(home, ".config"),
    XDG_DATA_HOME: path.join(home, ".local", "share"),
    XDG_STATE_HOME: path.join(home, ".local", "state"),
    XDG_CACHE_HOME: path.join(home, ".cache"),
  };
  const previousEnvironment = new Map(Object.keys(isolatedEnvironment).map((key) => [key, process.env[key]]));
  Object.assign(process.env, isolatedEnvironment);
  return () => {
    for (const [key, value] of previousEnvironment) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    fs.rmSync(home, { recursive: true, force: true });
  };
}

/** Execute a dataset repeatedly and produce a stable, machine-readable score artifact. */
export async function runEvalCommand(
  options: EvalCommandOptions,
  buildConfig: (options: EvalCommandOptions) => HarnessConfig,
  runner: EvalRunner = defaultRunner,
): Promise<EvalScoreDocument> {
  if (!options.dataset?.trim()) throw new Error("--dataset is required");
  const runs = parseEvalRuns(options.runs);
  const datasetPath = path.resolve(options.dataset);
  const loadedInstances = runner.loadDataset(datasetPath);
  let instances = loadedInstances;
  if (options.limit !== undefined) {
    const limit = parseEvalRuns(options.limit);
    instances = loadedInstances.slice(0, limit);
  }
  if (instances.length === 0) throw new Error("dataset contains no evaluation instances");

  const scores: EvalRunScore[] = [];
  for (let run = 1; run <= runs; run++) {
    const summary = await withRunHome(Boolean(options.isolatedHome), async () => {
      const config = buildConfig(options);
      const evaluator = runner.createEvaluator(config.workspace);
      return evaluator.runBenchmark(instances, config, "Nexus Evaluation");
    });
    scores.push(scoreRun(run, summary));
  }

  const document: EvalScoreDocument = {
    schemaVersion: 1,
    dataset: datasetPath,
    generatedAt: new Date().toISOString(),
    runs,
    isolatedHome: Boolean(options.isolatedHome),
    scores,
  };
  if (options.output) {
    const outputPath = path.resolve(options.output);
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    fs.writeFileSync(outputPath, `${JSON.stringify(document, null, 2)}\n`, { encoding: "utf8", mode: 0o600 });
  }
  return document;
}
