  summary.gate = summary.shapeMet && summary.contaminated === 0 && summary.ineligible === 0 && summary.falseAbsences === 0 && summary.falsePresences === 0 && summary.probeUnanswered === 0 && summary.steeringRate >= 0.95 ? "PASS" : "FAIL";
