    agents: expectedAgents,
    versions: Object.fromEntries(inputs.map(({ manifest }) => [manifest.config.agent, manifest.agentVersion.version])),
    model: reference.fingerprint,
    matchedRuns: grouped.size,
    tasks,
  };
}

