}
function datasetTaskTreeDigest(root) {
  let total = 0;
  let entriesSeen = 0;
  const hash = createHash("sha256");
  hash.update("nexus-task-tree-v2\0");
  const frame = (value) => {
    const bytes = Buffer.isBuffer(value) ? value : Buffer.from(value, "utf8");
    const size = Buffer.alloc(8);
    size.writeBigUInt64BE(BigInt(bytes.length));
    hash.update(size);
    hash.update(bytes);
  };
  const walk = (dir, depth) => {
    if (depth > MAX_TASK_TREE_DEPTH) throw new Error(`dataset task tree exceeds ${MAX_TASK_TREE_DEPTH} directory levels`);
    const handle = fs.opendirSync(dir);
    try {
      const entries = [];
      let entry;
      while ((entry = handle.readSync()) !== null) {
        entriesSeen++;
        if (entriesSeen > MAX_TASK_TREE_ENTRIES) throw new Error(`dataset task tree exceeds ${MAX_TASK_TREE_ENTRIES} entries`);
        entries.push(entry);
      }
      entries.sort((a, b) => a.name.localeCompare(b.name));
      for (const entry of entries) {
        const item = path.join(dir, entry.name);
        const relative = path.relative(root, item).split(path.sep).join("/");
        const stat = fs.lstatSync(item);
        if (stat.isSymbolicLink()) throw new Error(`dataset task contains a symlink: ${relative}`);
        if (stat.isDirectory()) {
          hash.update("D");
          frame(relative);
          walk(item, depth + 1);
          continue;
        }
        if (!stat.isFile()) throw new Error(`dataset task contains a special file: ${relative}`);
        hash.update("F");
        frame(relative);
        let fd;
        try {
          fd = fs.openSync(item, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
          const current = fs.fstatSync(fd);
      // T3 drives the sidecar, the operator channel that carries steering, with the same model, budgets and limits.
      const checkout = agentIdentity.argsPrefix[0] === path.join(ROOT, "cli/dist/index.js");
      // An installed package is <package>/bin/nexus with the sidecar at <package>/lib/cli/dist/sidecar.js.
      const packageDir = checkout ? null : path.dirname(path.dirname(fs.realpathSync(agentIdentity.command)));
      const sidecar = checkout ? path.join(ROOT, "cli/dist/sidecar.js") : path.join(packageDir, "lib/cli/dist/sidecar.js");
      if (!fs.existsSync(sidecar)) throw new Error(`T3 needs the Nexus sidecar at ${sidecar}`);
      if (packageDir) {
        // The launcher is bypassed, so the package itself must be mounted: it has to sit under sandboxRuntimeRoots.
        const roots = (config.sandboxRuntimeRoots ?? []).flatMap((root) => { try { return [fs.realpathSync(root)]; } catch { return []; } });
