  .command("eval <dataset>")
  .description("[experimental] Evaluate SWE-bench / benchmark dataset against Nexus Code harness")
  .option("-e, --endpoint <url>", "Local LLM endpoint (default: $LOCAL_LLM_ENDPOINT)")
