    console.log("\n" + scorecard);
    const outputPath = path.resolve(options.output || "eval-scorecard.md");
    fs.writeFileSync(outputPath, scorecard, "utf-8");
    console.log(pc.green(`✔ Scorecard saved to: ${outputPath}\n`));
  });

